#define TROJAN_URI_COUNT (sizeof( list_trojan_uri ) / sizeof( list_trojan_uri[0] )) #define BIGRAM_BITS 4096
//first bigram of each pattern, to skip quickly the patterns that cannot match; // only set when the first fragment has 2 characters or more static uint16_t trojan_bigram[ TROJAN_URI_COUNT ]; static bool trojan_has_bigram[ TROJAN_URI_COUNT ];
static inline uint16_t em_bigram( const char *s ){ return ( ((uint8_t)s[0]) * 31u + ((uint8_t)s[1]) ) % BIGRAM_BITS; }
//whether #uri contains the fragments of #pattern in order (fragments end after each '=') static inline bool em_match_fragments( const char *uri, const char *pattern ){ const char *frag = pattern, *eq, *found; char buf[ 256 ]; size_t len; while( *frag != '\0' ){ eq = strchr( frag, '=' ); len = (eq == NULL) ? strlen( frag ) : (size_t)(eq - frag + 1); if( len >= sizeof( buf )) return false; memcpy( buf, frag, len ); buf[ len ] = '\0'; found = strstr( uri, buf ); if( found == NULL ) return false; uri = found + len; frag += len; } return true; }
static inline int em_check_trojan_uri(const char * uri){ uint8_t bigrams[ BIGRAM_BITS / 8 ]; const char *c; size_t i; uint16_t h;
if( uri == NULL || uri[0] == '\0' ) return false;
//bigrams present in the URI memset( bigrams, 0, sizeof( bigrams )); for( c = uri; c[1] != '\0'; c++ ){ h = em_bigram( c ); bigrams[ h / 8 ] |= 1u << (h % 8); }
for( i=0; i<TROJAN_URI_COUNT; i++ ){ if( trojan_has_bigram[i] ){ h = trojan_bigram[i]; if( (bigrams[ h / 8 ] & (1u << (h % 8))) == 0 ) continue; } if( em_match_fragments( uri, list_trojan_uri[i] )) return true; } return false; }
//This fuction is called when the rules in this file being loaded into MMT-Security void on_load(){ size_t i; const char *p; for( i=0; i<TROJAN_URI_COUNT; i++ ){ p = list_trojan_uri[i]; trojan_has_bigram[i] = ( p[0] != '\0' && p[0] != '=' && p[1] != '\0' ); if( trojan_has_bigram[i] ) trojan_bigram[i] = em_bigram( p ); } mmt_debug("Rule 33.trojan: %zu URI patterns", TROJAN_URI_COUNT ); }//end on_load()
